-- Read-only. All ten violation counts must equal zero.
SELECT 'import_tables' check_name,ABS(4-COUNT(*)) violations FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_import_batch','institution_import_item','institution_import_event','institution_import_external_reference');
SELECT 'import_states' check_name,COUNT(*) violations FROM institution_import_batch WHERE category NOT IN ('Student','Teacher') OR revision<1 OR total_rows<1 OR valid_rows+invalid_rows<>total_rows OR JSON_TYPE(warnings_json)<>'ARRAY' OR (state='Preview' AND (payload IS NULL OR result_json IS NOT NULL)) OR (state='Completed' AND (payload IS NOT NULL OR result_json IS NULL)) OR (state='Expired' AND (payload IS NOT NULL OR result_json IS NOT NULL));
SELECT 'import_completed_counts' check_name,COUNT(*) violations FROM institution_import_batch b WHERE b.state='Completed' AND (SELECT COUNT(*) FROM institution_import_item i WHERE i.institution_id=b.institution_id AND i.batch_id=b.id)<>b.total_rows;
SELECT 'import_no_uncommitted_items' check_name,COUNT(*) violations FROM institution_import_item i JOIN institution_import_batch b ON b.institution_id=i.institution_id AND b.id=i.batch_id WHERE b.state<>'Completed';
SELECT 'import_target_shapes' check_name,COUNT(*) violations FROM institution_import_item WHERE NOT((category='Student' AND student_id IS NOT NULL AND teacher_id IS NULL) OR (category='Teacher' AND student_id IS NULL AND teacher_id IS NOT NULL));
SELECT 'import_reference_shapes' check_name,COUNT(*) violations FROM institution_import_external_reference WHERE NOT((category='Student' AND student_id IS NOT NULL AND teacher_id IS NULL) OR (category='Teacher' AND student_id IS NULL AND teacher_id IS NOT NULL)) OR CHAR_LENGTH(TRIM(reference))=0;
SELECT 'import_event_sequence' check_name,COUNT(*) violations FROM (SELECT b.institution_id,b.id,b.revision,COUNT(e.id) n,MIN(e.revision) lo,MAX(e.revision) hi FROM institution_import_batch b LEFT JOIN institution_import_event e ON e.institution_id=b.institution_id AND e.batch_id=b.id GROUP BY b.institution_id,b.id,b.revision HAVING n<>b.revision OR lo<>1 OR hi<>b.revision) x;
SELECT 'import_event_actor' check_name,COUNT(*) violations FROM institution_import_event e JOIN institution_import_batch b ON b.institution_id=e.institution_id AND b.id=e.batch_id WHERE NOT((e.actor_kind='User' AND e.actor_user_id=b.actor_user_id AND e.actor_membership_id=b.actor_membership_id AND e.action IN ('Previewed','Remapped','Confirmed')) OR (e.actor_kind='Retention' AND e.actor_user_id IS NULL AND e.actor_membership_id IS NULL AND e.action='Expired'));
SELECT 'import_foreign_keys' check_name,ABS(13-COUNT(*)) violations FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_import_batch','institution_import_item','institution_import_event','institution_import_external_reference');
SELECT 'import_triggers' check_name,ABS(12-COUNT(*)) violations FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('import_batch_insert','import_batch_update','import_batch_delete','import_external_insert','import_external_update','import_external_delete','import_item_insert','import_item_update','import_item_delete','import_event_insert','import_event_update','import_event_delete');
